    {
      "id": "evaluateWeather1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate Weather"
      },
      "inputs": {
        "script": "var weather = $vars.getBellevueWeather1.output.current_weather;\nvar temp = weather.temperature;\nvar windspeed = weather.windspeed;\nvar weathercode = weather.weathercode;\n\n// Nice day criteria:\n//   WMO code 0-2 (clear / mainly clear / partly cloudy)\n//   Temperature 60-85°F  (connector requested fahrenheit)\n//   Wind < 32.2 km/h (~20 mph)  -- Open-Meteo returns km/h by default\nvar isNice = (weathercode <= 2) && (temp >= 60) && (temp <= 85) && (windspeed < 32.2);\n\nvar conditionLabel =\n  weathercode === 0 ? 'clear skies' :\n  weathercode === 1 ? 'mainly clear' :\n  weathercode === 2 ? 'partly cloudy' :\n  weathercode === 3 ? 'overcast' :\n  (weathercode >= 51 && weathercode <= 57) ? 'drizzle' :\n  (weathercode >= 61 && weathercode <= 67) ? 'rainy' :\n  (weathercode >= 71 && weathercode <= 77) ? 'snowy' :\n  (weathercode >= 95) ? 'stormy' :\n  'unsettled conditions';\n\nreturn {\n  isNiceDay: isNice,\n  temperature: temp,\n  windspeed: windspeed,\n  weathercode: weathercode,\n  conditionLabel: conditionLabel,\n  summary: isNice\n    ? 'Yes - it is a nice day in Bellevue, WA! ' + conditionLabel + ' at ' + temp + '°F with ' + windspeed + ' km/h winds.'\n    : 'No - not the nicest day in Bellevue, WA. ' + conditionLabel + ' at ' + temp + '°F with ' + windspeed + ' km/h winds.'\n};"
      }
    },
    {
      "id": "isNiceDay1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Is it a nice day?"
      },
